import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/ChatSidebar.css";

const ChatSidebar = ({ user, conversations, setConversations, onSelectConversation }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);

  useEffect(() => {
    if (!user || !user.userId) return;

    const fetchConversations = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/conversations/${user.userId}`);
        console.log("✅ Fetched conversations:", res.data);
        setConversations(res.data);
      } catch (err) {
        console.error("❌ Failed to fetch conversations:", err);
      }
    };

    fetchConversations();
  }, [user, setConversations]);

  const handleSearch = async (e) => {
    const value = e.target.value;
    setSearchTerm(value);

    if (!value) {
      setSearchResults([]);
      return;
    }

    try {
      const res = await axios.get(`http://localhost:5000/api/profile/search?username=${value}`);
      setSearchResults(res.data);
    } catch (err) {
      console.error("❌ Search failed:", err);
    }
  };

  const handleUserClick = async (selectedUser) => {
    try {
      const existing = conversations.find((c) =>
        c.participantUsernames.includes(selectedUser.username)
      );

      if (existing) {
        onSelectConversation(existing);
        return;
      }

      const res = await axios.post("http://localhost:5000/api/conversations", {
        senderId: user.userId,
        receiverId: selectedUser._id,
        senderUsername: user.username,
        receiverUsername: selectedUser.username,
      });

      const newConversation = res.data;
      setConversations((prev) => [...prev, newConversation]);
      onSelectConversation(newConversation);
      setSearchTerm("");
      setSearchResults([]);
    } catch (err) {
      console.error("❌ Error starting new conversation:", err);
    }
  };

  return (
    <div className="chat-sidebar">
      <h3>Messages</h3>

      <input
        className="chat-search"
        type="text"
        placeholder="Search users..."
        value={searchTerm}
        onChange={handleSearch}
      />

      <ul className="search-results">
        {searchResults.map((user) => (
          <li key={user._id} onClick={() => handleUserClick(user)}>
            {user.username}
          </li>
        ))}
      </ul>

      <ul className="conversation-list">
        {conversations.length === 0 && <p>No conversations found.</p>}
        {conversations.map((c) => {
          const partner = c.participantUsernames.find((u) => u !== user.username);
          return (
            <li key={c._id} onClick={() => onSelectConversation(c)}>
              <strong>{partner}</strong>
              <br />
              <span>{c.lastMessage}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
};

export default ChatSidebar;
